((root,factory)=>{const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.BasicLimitLesson=api;})(typeof window==='undefined'?globalThis:window,()=>{'use strict';const distances=[1,0.5,0.1,0.01,0.001],cases={polynomial:{strategy:'substitute',limit:5,ymin:-1,ymax:18,ticks:[0,4,8,12,16]},factor:{strategy:'factor',limit:4,ymin:0,ymax:7,ticks:[0,2,4,6]},radical:{strategy:'conjugate',limit:0.25,ymin:0,ymax:0.6,ticks:[0,0.2,0.4,0.6]},absolute:{strategy:'sides',limit:null,ymin:-2,ymax:2,ticks:[-2,-1,0,1,2]}};function branch(kind,x){if(kind==='polynomial')return x*x+1;if(kind==='factor')return x+2;if(kind==='radical')return x<-2?null:1/(Math.sqrt(x+2)+2);if(kind==='absolute')return x<2?-1:1;return null;}function value(kind,x){return kind!=='polynomial'&&x===2?null:branch(kind,x);}function approach(kind,d){if(!cases[kind]||!Number.isFinite(d)||d<=0)return null;return {leftX:2-d,rightX:2+d,leftY:value(kind,2-d),rightY:value(kind,2+d),at:value(kind,2),limit:cases[kind].limit};}function point(kind,x,y){const c=cases[kind];return {x:50+x/4*560,y:310-(y-c.ymin)/(c.ymax-c.ymin)*280};}function curve(kind,side){return Array.from({length:181},(_,i)=>{const x=side==='left'?2*i/180:2+2*i/180,y=kind==='absolute'?(side==='left'?-1:1):branch(kind,x);return point(kind,x,y);});}return {distances,cases,branch,value,approach,point,curve};});